private static long walk(final JsonIterator ji) {
  return switch (ji.whatIsNext()) {
    case OBJECT -> {
      final long[] sum = new long[1];
      ji.testObject(sum, FIELD_WALKER);
      yield sum[0];
    }
    case ARRAY -> {
      long sum = 0;
      while (ji.readArray()) {
        sum += walk(ji);
      }
      yield sum;
    }
    default -> {
      ji.skip();
      yield 1;
    }
  };
}
